package vn.rtr.aeris.operator01;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.util.zip.*;
/** Integrity-only closed/prefix snapshot; never declares mission acceptance. Original tail is retained. */
public final class RawArchive96{
 public static final int RAW=32*1024*1024,MAX=40*1024*1024;private static final Pattern LINE=Pattern.compile("\\{\"n\":([0-9]+),\"previous\":\"([a-f0-9]*)\",\"elapsedMs\":([0-9]+),\"kind\":\"([A-Z0-9_]{1,60})\",\"dataBase64\":\"([A-Za-z0-9+/=]*)\",\"sha256\":\"([a-f0-9]{64})\"\\}");
 public static final class Prefix{public final String head,lastKind;public final int records,committedBytes,tailBytes;public final byte[] meta;Prefix(String h,String k,int n,int c,int t,byte[]m){head=h;lastKind=k;records=n;committedBytes=c;tailBytes=t;meta=m;}public boolean closed(){return tailBytes==0&&lastKind.equals("CLOSED");}}
 public static Prefix replay(byte[]raw)throws IOException{if(raw.length==0||raw.length>RAW)throw new IOException("RAW96_BOUND");int start=0,n=0;long last=-1;String head="",kind="";byte[]meta=null;for(int i=0;i<raw.length;i++){if(raw[i]!=10)continue;if(i-start>180000)throw new IOException("RAW96_LINE_BOUND");String line=new String(raw,start,i-start,StandardCharsets.US_ASCII);Matcher m=LINE.matcher(line);if(!m.matches()||Integer.parseInt(m.group(1))!=++n||!m.group(2).equals(head))throw new IOException("RAW96_ORDER_FORMAT");long t=Long.parseLong(m.group(3));if(t<last)throw new IOException("RAW96_CLOCK");last=t;byte[]data;try{data=Base64.getDecoder().decode(m.group(5));}catch(Exception e){throw new IOException("RAW96_BASE64");}if(data.length>131072||!Base64.getEncoder().encodeToString(data).equals(m.group(5)))throw new IOException("RAW96_PAYLOAD");String body=line.substring(0,line.lastIndexOf(",\"sha256\""))+"}";if(!DraftStore.hash(body.getBytes(StandardCharsets.US_ASCII)).equals(m.group(6)))throw new IOException("RAW96_SHA");kind=m.group(4);if(n==1){if(!kind.equals("META"))throw new IOException("RAW96_META_REQUIRED");meta=data;}head=m.group(6);start=i+1;}if(n==0||raw.length-start>180000)throw new IOException("RAW96_PREFIX_REQUIRED");return new Prefix(head,kind,n,start,raw.length-start,meta);}
 public static String manifest(LinkedHashMap<String,byte[]>files,String context)throws IOException{if(files.size()<2||files.size()>3||!files.containsKey("raw.jsonl")||!files.containsKey("source-meta.json")||context==null||context.getBytes(StandardCharsets.UTF_8).length>16384)throw new IOException("RAW96_MEMBERS");Prefix p=replay(files.get("raw.jsonl"));if(!Arrays.equals(p.meta,files.get("source-meta.json")))throw new IOException("RAW96_META_BINDING");StringBuilder entries=new StringBuilder();long total=0;for(Map.Entry<String,byte[]>e:files.entrySet()){if(!Arrays.asList("raw.jsonl","source-meta.json","review.json").contains(e.getKey())||e.getValue().length==0||(!e.getKey().equals("raw.jsonl")&&e.getValue().length>1024*1024))throw new IOException("RAW96_MEMBER_BOUND");total+=e.getValue().length;if(total>MAX-16384)throw new IOException("RAW96_EXPANDED_BOUND");if(entries.length()>0)entries.append(',');entries.append("{\"name\":").append(Json.quote(e.getKey())).append(",\"bytes\":").append(e.getValue().length).append(",\"sha256\":").append(Json.quote(DraftStore.hash(e.getValue()))).append('}');}return "{\"format\":\"aeris-native96-raw\",\"version\":1,\"sourceAuthenticated\":false,\"authorityRestorable\":false,\"actualImages\":0,\"missionAcceptance\":\"NOT_ASSERTED_BY_PACKAGE\",\"context\":"+context+",\"raw\":{\"extent\":"+Json.quote(p.closed()?"CLOSED_RAW":p.tailBytes>0?"TORN_TAIL_RETAINED":"UNTERMINATED_PREFIX")+",\"records\":"+p.records+",\"head\":"+Json.quote(p.head)+",\"committedBytes\":"+p.committedBytes+",\"tailBytes\":"+p.tailBytes+"},\"files\":["+entries+"]}";}
 public static byte[] build(LinkedHashMap<String,byte[]>files,String context)throws IOException{byte[]manifest=manifest(files,context).getBytes(StandardCharsets.UTF_8);ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){put(z,"manifest.json",manifest);for(Map.Entry<String,byte[]>e:files.entrySet())put(z,e.getKey(),e.getValue());}byte[]result=out.toByteArray();if(result.length>MAX)throw new IOException("RAW96_ZIP_BOUND");return result;}
 private static void put(ZipOutputStream z,String name,byte[]b)throws IOException{ZipEntry e=new ZipEntry(name);e.setTime(0);e.setMethod(ZipEntry.STORED);e.setSize(b.length);e.setCompressedSize(b.length);CRC32 c=new CRC32();c.update(b);e.setCrc(c.getValue());z.putNextEntry(e);z.write(b);z.closeEntry();}
 public static byte[] read(Path p,int bound)throws IOException{if(Files.isSymbolicLink(p)||!Files.isRegularFile(p)||Files.size(p)>bound)throw new IOException("RAW96_PATH_BOUND");return Files.readAllBytes(p);}
 public static void publish(Path p,byte[]b)throws IOException{if(b.length>MAX||Files.exists(p,LinkOption.NOFOLLOW_LINKS))throw new IOException("RAW96_EXCLUSIVE");try(java.nio.channels.FileChannel c=java.nio.channels.FileChannel.open(p,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){java.nio.ByteBuffer v=java.nio.ByteBuffer.wrap(b);while(v.hasRemaining())c.write(v);c.force(true);}try(java.nio.channels.FileChannel d=java.nio.channels.FileChannel.open(p.getParent(),StandardOpenOption.READ)){d.force(true);}}
}
